def flood_fill_from_neighbors(r, c, inp_val, inp):
    """Flood fill 1s adjacent to position (r,c)"""
    comp = set()
    queue = deque()

    # Start from neighbors that are inp_val
    for nr, nc in get_neighbors(r, c):
        if 0 <= nr < rows and 0 <= nc < cols and inp[nr][nc] == inp_val:
            comp.add((nr, nc))
            queue.append((nr, nc))

    while queue:
        r2, c2 = queue.popleft()
        for nr, nc in get_neighbors(r2, c2):
            if 0 <= nr < rows and 0 <= nc < cols:
                if inp[nr][nc] == inp_val and (nr, nc) not in comp:
                    comp.add((nr, nc))
                    queue.append((nr, nc))

    return comp

